const unpack = (a) => Object.fromEntries(SFCT_ANALYTES.map((k, i) => [k, a[i]]));
/** The SFCT library: { [id]: { name, nameAr, region, recipePage, tablePage, yield, ingredients, per100g, fullRecipe, recipeGrams } } */
export const SFCT_LIBRARY = Object.fromEntries(Object.entries(ROWS).map(([id, r]) => {
  const per100g = unpack(r.per100g);
  const fullRecipe = unpack(r.fullRecipe);
  // Cooked weight of the whole recipe, from the book's own energy values (full recipe ÷ per 100 g).
  const recipeGrams = per100g.energyKj && fullRecipe.energyKj ? Math.round((fullRecipe.energyKj / per100g.energyKj) * 100) : null;
  return [id, { ...r, ingredients: r.ingredients.map(([name, quantity, group]) => ({ name, quantity, group: group ?? null })), per100g, fullRecipe, recipeGrams }];
}));
